BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('DS-109-2-39','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考社區發展工作綱要第22條。考試時條文（1991-05-01 訂定發布，第22條其後未修正）規定推動社區發展業務績效良好之社區，各級主管機關應予表揚或指定示範觀摩、頒發獎狀或獎品、發給社區發展獎助金之獎勵，官方答案(C)②④⑤當時正確。現行條文：本綱要已於 2025-07-01 經衛生福利部發布廢止並即日生效，第22條已無現行效力。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050077'),('DS-110-2-39','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-08-21。本題考社區發展工作綱要第2條。考試時條文（1991-05-01 訂定發布，第2條其後未修正）規定社區係指經鄉（鎮、市、區）社區發展主管機關劃定，供為依法設立社區發展協會，推動社區發展工作之組織與活動區域，社區居民係指設戶籍並居住本社區之居民，選項(D)僅稱居住在該社區之人口，與條文不符，官方答案(D)當時正確。現行條文：本綱要已於 2025-07-01 經衛生福利部發布廢止並即日生效，第2條已無現行效力。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050077'),('HBSE-105-1-030','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考校園性別事件之調查處理。考試後性別平等教育法經 2018、2022 年修正及 2023-08-16 全文修正，校園性侵害性騷擾或性霸凌防治準則經 2019 年全文修正、2024-03-06 全文修正並更名為校園性別事件防治準則。現行校園性別事件防治準則第22條規定調查小組以三人或五人為原則，性別平等教育法第33條規定調查小組女性成員不得少於成員總數二分之一，且具校園性別事件調查專業素養之專家學者人數於學校應占成員總數三分之一以上，準則第23條規定該等專家學者須經主管機關核可納入調查專業人才庫，選項(D)所述規定仍相同；準則第22條另規定當事人之輔導人員應迴避該事件之調查工作（選項A錯誤），第30條揭示避免重複詢問原則（選項B錯誤），第20條規定疑似被害人不願配合調查時仍應提供必要之輔導或協助，並無得暫時擱置之規定（選項C錯誤）。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0080067'),('HBSE-105-1-032','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考校園霸凌防制準則。考試時條文（2012-07-26 訂定發布）：第3條規定校園霸凌包括校園內、外所發生之霸凌行為（選項A錯誤）；第8條規定學校對被霸凌人及曾有霸凌行為或有該傾向之學生應積極提供協助、主動輔導（選項B錯誤）；第11條規定被霸凌人或其法定代理人得向行為人於行為發生時所屬之學校申請調查，學校應於三日內召開防制校園霸凌因應小組會議，並於受理申請之次日起二個月內處理完畢（選項C正確），學校經大眾傳播媒體報導知有疑似校園霸凌事件時亦應調查處理（選項D錯誤）。現行條文：本準則經 2020-07-21 及 2024-04-17 全文修正，第4條仍規定校園霸凌包括校園內、外之霸凌行為，第18條改為向調查學校「檢舉」，媒體報導視同檢舉；處理單位改為防制校園霸凌委員會及處理小組，第43條規定處理小組應於召開第一次調和或調查會議之日起二個月內完成調和或調查報告，必要時得延長二次、每次不逾一個月，選項(C)所述之因應小組及處理期限已不符現行條文。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0020081'),('HBSE-107-2-010','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考校園霸凌。考試時校園霸凌防制準則（2012-07-26 訂定發布）第20條規定校園霸凌事件情節嚴重者，學校應即請求警政、社政機關（構）或檢察機關協助（選項C正確）；第11條規定疑似校園霸凌事件之被霸凌人或其法定代理人得向行為人於行為發生時所屬之學校申請調查（選項D正確）；選項(B)霸凌角色固定不變為錯誤敘述，官方答案(B)當時正確。現行條文：本準則經 2020-07-21 及 2024-04-17 全文修正，第61條改為校園霸凌事件情節重大者，學校「得」請求警政、社政機關（構）或司法機關協助，選項(C)所稱「應請求警政、社政或檢察機關協助」已不符現行條文；第18條改為被行為人、其法定代理人或實際照顧者得向行為人於行為發生時所屬之學校檢舉。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0020081'),('HBSE-107-2-016','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考病人自主權利法。第8條規定具完全行為能力之人得為預立醫療決定，並得隨時以書面撤回或變更；第14條規定病人符合末期病人、不可逆轉之昏迷、永久植物人、極重度失智等特定臨床條件，經二位具相關專科醫師資格之醫師確診後，醫療機構或醫師始得依預立醫療決定終止、撤除或不施行維持生命治療，並非不論醫療技術能否治療都放棄救治（選項D錯誤）。第8、14條未曾修正，考試時條文與現行條文相同；惟民法第12條於 2021-01-13 修正、自 2023-01-01 施行，成年年齡改為十八歲，現行法下十八歲以上具完全行為能力者即得為預立醫療決定，選項(A)所稱年滿20歲者仍得簽署，不影響本題答案。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020189'),('HBSE-115-1-022','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-02-07。本題考毒品危害防制條例第2條：毒品依其成癮性、濫用性及對社會危害性分為四級，第二級例示罌粟、古柯、大麻、安非他命、配西汀、潘他唑新及其相類製品（如附表二），選項(B)第二級正確。最後修正公布日：第2條 2020-01-15，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=C0000008'),('SP-115-2-040','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-07-25。本題考性騷擾防治法第14條：權勢性騷擾事件，於知悉事件發生後三年內提出申訴，但自性騷擾事件發生之日起逾七年者不得提出。本條為 2023-08-16 全文修正之條文，自 2024-03-08 施行，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050074'),('SP104-1-36','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考人口販運防制法。考試時條文（2009-01-23 制定公布，2016-05-25 僅修正第2、4、20條）第16條規定經鑑別為人口販運被害人，且無合法有效之停（居）留許可者，中央主管機關應核發六個月以下效期之臨時停留許可，官方答案(C)當時正確。現行條文：本法 2023-06-14 全文修正（2024-01-01 施行），第14條改為經鑑別為人口販運被害人者，中央主管機關應依其申請核發一年效期之居留許可，並得延長，每次延長不得逾一年，已無六個月以下效期臨時停留許可之規定。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0080177'),('SP107-2-23','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考少年事件處理法第53條：保護管束與感化教育之執行，其期間均不得逾三年。本條自 1997-10-29 全文修正公布後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=C0010011'),('SP108-2-22','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考少年事件處理法第26條：少年法院於必要時，得裁定責付於少年之法定代理人、家長、最近親屬、現在保護少年之人或其他適當之機關（構）、團體或個人，或命收容於少年觀護所，並無命收容於社區日照中心之處置（選項C）。考試時適用 2019-06-19 修正公布（自公布日施行）之條文；2023-06-21 再修正第26條，增列責付對象及責付時得命遵守事項，責付於法定代理人、最近親屬及收容於少年觀護所之規定未變，就本題規定考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=C0010011'),('SP112-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-02-18。本題考長期照顧服務機構法人條例第36條：長照機構社團法人應提撥前一會計年度收支結餘之百分之十以上，辦理有關研究發展、人才培訓、長照宣導教育及社會福利。本條例 2018-01-31 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0070051'),('SW-104-1-25','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考專科社會工作師分科甄審及接受繼續教育辦法第3條：專科社會工作師之分科為醫務、心理衛生、兒童少年婦女及家庭、老人、身心障礙五科，選項(D)長期照顧不在其中。第3條自 2009-07-13 訂定發布後未曾修正（其後 2015、2016、2020 年修正均未涉及），考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050170'),('SW-106-2-34','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考社區發展協會之組織性質。考試時社區發展工作綱要第8條規定會員（會員代表）大會為社區發展協會最高權力機構，選項(C)「理事會為最高權力機關」錯誤，官方答案(C)當時正確。現行條文：本綱要已於 2025-07-01 經衛生福利部發布廢止並即日生效；人民團體法第8條於 2021-01-27 修正為發起人須為成年並應有三十人以上，民法第12條自 2023-01-01 起以滿十八歲為成年，選項(D)所稱年滿20歲已非現行規定。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050077'),('SW-107-2-18','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考家事事件法。第3條將家事事件分為甲、乙、丙、丁、戊五類，非四類（選項A錯誤）；第18條規定審判長或法官得命家事調查官就特定事項調查事實（選項B）；第15條規定法院得選任程序監理人（選項C）；第11條規定未成年人表達意願或陳述意見時，必要者，法院應通知主管機關指派社會工作人員或其他適當人員陪同在場（選項D）。第11、15、18條考試後未再修正；第3條於 2023-06-21 修正（2026-08-01 施行），僅將丁類「停止緊急安置或強制住院事件」改為「嚴重病人保護安置事件」，仍分五類，就本題規定考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=B0010048'),('SW-108-2-02','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考專科社會工作師分科甄審及接受繼續教育辦法第3條：專科社會工作師之分科為醫務、心理衛生、兒童少年婦女及家庭、老人、身心障礙五科，選項(C)原住民不在其中。第3條自 2009-07-13 訂定發布後未曾修正（其後 2015、2016、2020 年修正均未涉及），考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050170'),('SW-108-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考學生輔導法三級輔導之分工。考試時第6條規定學校應提供發展性、介入性及處遇性三級輔導，第12條規定學校及主管機關所置專業輔導人員負責執行處遇性輔導措施（學校社會工作師屬專業輔導人員）。2024-12-18 修正第6、12條，現行第12條仍規定學校主管機關所置專業輔導人員負責執行處遇性輔導，就本題規定考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0070058'),('SW-109-1-37','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-02-15。本題考學生輔導法第11條。考試時條文（2014-11-12 制定公布，施行至 2026-12-31）規定專科以上學校學生一千二百人以下者，應置專業輔導人員至少一人，官方答案(C)當時正確。現行條文：第11條於 2024-12-18 修正公布，行政院定自 2027-01-01 施行，改為專科以上學校學生九百人以下者應置專任專業輔導人員至少一人，超過九百人者每滿九百人增置一人。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0070058'),('SW-109-2-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考社會工作師業務過失可能涉及之刑事責任。中華民國刑法第284條過失傷害罪、第310條誹謗罪及第315條等妨害秘密罪均為刑法規定；損害賠償屬民法第184條之民事責任，與刑法無關（選項D）。最後修正公布日：中華民國刑法第284條 2019-05-29、第310條 2019-12-25、第315條 2019-12-25，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=C0000001'),('SW-110-1-34','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-02-06。本題考學生輔導法第11條。考試時條文（2014-11-12 制定公布，施行至 2026-12-31）規定高級中等以下學校班級數達五十五班以上者應至少置專任專業輔導人員一人（選項D正確、選項C「50班」錯誤），主管機關所轄學校數合計二十校以下者置一人（選項B），專科以上學校學生一千二百人以下者應置專業輔導人員至少一人（選項A），官方答案(C)當時正確。現行條文：第11條於 2024-12-18 修正公布，行政院定自 2027-01-01 施行，改由各高級中等以下學校主管機關依所主管學校總數（二十校以下置一人）及學生總數除以四千五百至五千之基數置專任專業輔導人員，不再以學校班級數五十五班計算，專科以上學校改為學生九百人以下置一人，選項(A)(D)將不符修正後條文。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0070058'),('SW-110-2-13','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-08-21。本題考病人自主權利法。第8條規定預立醫療決定得隨時以書面撤回或變更（①錯誤）；第9條規定意願人、二親等內之親屬至少一人及醫療委任代理人應參與預立醫療照護諮商（②「三親等」錯誤）；第1條規定立法目的為尊重病人醫療自主、保障其善終權益，促進醫病關係和諧（③正確）。考試時第10條（2021-01-20 修正）規定醫療委任代理人以成年且具行為能力之人為限，當時民法第12條規定滿二十歲為成年，④「20歲以上」與當時規定相符，官方答案(A)③④當時正確。現行條文：民法第12條於 2021-01-13 修正、自 2023-01-01 施行，滿十八歲為成年，醫療委任代理人已不以二十歲以上為限，④已不符現行條文，依現行條文本題已無正確選項。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020189'),('SW-111-1-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題考成年監護宣告。民法第1111條規定法院為監護之宣告時，應依職權就配偶、四親等內之親屬、最近一年有同居事實之其他親屬、主管機關、社會福利機構或其他適當之人選定監護人，故社會福利機構（①）及直轄市、縣（市）政府社會局等主管機關（②）依法均得擔任監護人；③④為實務統計敘述，非法規內容。第1111條最後修正公布日 2008-05-23（第1111條之2 照護機構不得為監護人之限制最後修正於 2015-01-14），本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=B0000001'),('SW-111-1-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題考病人自主權利法。第3條第7款規定緩和醫療指為減輕或免除病人之生理、心理及靈性痛苦，施予緩解性、支持性之醫療照護（選項D正確）；第1條規定立法目的為尊重病人醫療自主，非以家屬為核心（選項B錯誤）；第14條規定適用之臨床條件包括末期病人、不可逆轉之昏迷、永久植物人、極重度失智等，非僅末期病人（選項C錯誤）；本法並非安樂死或協助自殺之法規（選項A錯誤）。第1、3、14條自 2016-01-06 制定公布後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020189'),('SW-112-2-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2023-07-29。本題考國民小學與國民中學未入學或中途輟學學生通報及復學輔導辦法第2條：中途輟學學生指國民小學及國民中學學生未經請假、請假未獲准或不明原因未到校上課連續達三日以上。本辦法 2017-08-23 全文修正發布，2020-06-08 僅修正第3條，第2條其後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0070015');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>24 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>24 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'86f3dbecc29b1eb01d65f52046e136f0' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_15, count(*) FILTER (WHERE q.legal_status='changed') changed_9, count(*) total_24 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
